head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate = function() {
    scwin.simulateWrapper('#wq_uuid_3_input', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#wq_uuid_3_input', 'key-sequence', {
        sequence: '일'
    });
}
scwin.checkVal1 = function() {
    if (WebSquare.wUnit.getDomById($p.id + 'wq_uuid_3_itemTable')) {
        return WebSquare.wUnit.getDomById($p.id + 'wq_uuid_3_itemTable').style.display == 'none';
    }
    return true;
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#wq_uuid_3_input', 'key-sequence', {
        sequence: '이'
    });
}
scwin.checkVal2 = function() {
    if (WebSquare.wUnit.getDomById($p.id + 'wq_uuid_3_itemTable')) {
        return WebSquare.wUnit.getDomById($p.id + 'wq_uuid_3_itemTable').style.display == 'none';
    }
    return true;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
